// Small typed client for the cactusTrade API. Types come from the OpenAPI contract
// (src/lib/schema.d.ts, generated by `pnpm gen:api`). The session lives in an HttpOnly
// cookie; state-changing calls send the CSRF token the server gave at sign-in.
import type { components } from "./schema";

export type User = components["schemas"]["User"];
export type Me = components["schemas"]["Me"];
export type Role = components["schemas"]["Role"];
export type ApiKey = components["schemas"]["ApiKey"];
export type CreatedApiKey = components["schemas"]["CreatedApiKey"];
export type Credential = components["schemas"]["Credential"];
export type SystemStatus = components["schemas"]["SystemStatus"];
export type PublicStatus = components["schemas"]["PublicStatus"];
export type AuditEntry = components["schemas"]["AuditEntry"];
export type Problem = components["schemas"]["Problem"];
export type BrokerCheck = components["schemas"]["BrokerCheck"];
export type Portfolio = components["schemas"]["Portfolio"];
export type MarketSession = components["schemas"]["MarketSession"];
export type Instrument = components["schemas"]["Instrument"];
export type WatchItem = components["schemas"]["WatchItem"];
export type Quote = components["schemas"]["Quote"];
export type EventFeed = components["schemas"]["EventFeed"];
export type AppEvent = components["schemas"]["Event"];
export type RiskLimits = components["schemas"]["RiskLimits"];
export type LlmSetup = components["schemas"]["LlmSetup"];
export type Account = components["schemas"]["Account"];
export type Theme = components["schemas"]["Theme"];
export type ThemeInput = components["schemas"]["ThemeInput"];
export type Industry = components["schemas"]["Industry"];
export type Review = components["schemas"]["Review"];
export type ReviewBoard = components["schemas"]["ReviewBoard"];
export type ScanResult = components["schemas"]["ScanResult"];
export type AccountKeys = components["schemas"]["AccountKeys"];
export type AccountShare = components["schemas"]["AccountShare"];
export type LlmConfig = components["schemas"]["LlmConfig"];
export type LlmTestResult = components["schemas"]["LlmTestResult"];

export class ApiError extends Error {
  constructor(
    public status: number,
    public problem?: Problem,
  ) {
    super(problem?.detail || problem?.title || `HTTP ${status}`);
  }
}

let csrf = "";
export function setCsrf(token: string | undefined) {
  csrf = token ?? "";
  try {
    if (csrf) sessionStorage.setItem("cactustrade.csrf", csrf);
    else sessionStorage.removeItem("cactustrade.csrf");
  } catch {
    /* storage unavailable: the in-memory token still works */
  }
}

export async function request<T>(method: string, path: string, body?: unknown): Promise<T> {
  const headers: Record<string, string> = { Accept: "application/json" };
  if (body !== undefined) headers["Content-Type"] = "application/json";
  if (method !== "GET" && csrf) headers["X-CSRF-Token"] = csrf;
  const res = await fetch(path, {
    method,
    headers,
    credentials: "same-origin",
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  if (res.status === 204) return undefined as T;
  const text = await res.text();
  const data = text ? JSON.parse(text) : undefined;
  if (!res.ok) throw new ApiError(res.status, data as Problem);
  return data as T;
}

export const api = {
  publicStatus: () => request<PublicStatus>("GET", "/api/v1/public/status"),
  login: async (username: string, password: string) => {
    const me = await request<Me>("POST", "/api/v1/auth/login", { username, password });
    setCsrf(me.csrfToken);
    return me;
  },
  logout: async () => {
    await request<void>("POST", "/api/v1/auth/logout");
    setCsrf(undefined);
  },
  me: async () => {
    const me = await request<Me>("GET", "/api/v1/auth/me");
    setCsrf(me.csrfToken);
    return me;
  },
  changePassword: (currentPassword: string, newPassword: string) =>
    request<void>("POST", "/api/v1/auth/password", { currentPassword, newPassword }),
  status: () => request<SystemStatus>("GET", "/api/v1/system/status"),
  users: () => request<User[]>("GET", "/api/v1/users"),
  createUser: (username: string, password: string, role: Role) =>
    request<User>("POST", "/api/v1/users", { username, password, role }),
  updateUser: (id: string, patch: { role?: Role; disabled?: boolean; password?: string }) =>
    request<User>("PATCH", `/api/v1/users/${encodeURIComponent(id)}`, patch),
  deleteUser: (id: string) => request<void>("DELETE", `/api/v1/users/${encodeURIComponent(id)}`),
  apiKeys: () => request<ApiKey[]>("GET", "/api/v1/api-keys"),
  createApiKey: (name: string, role: Role, expiresInDays: number) =>
    request<CreatedApiKey>("POST", "/api/v1/api-keys", { name, role, expiresInDays }),
  revokeApiKey: (id: string) => request<void>("DELETE", `/api/v1/api-keys/${encodeURIComponent(id)}`),
  credentials: () => request<Credential[]>("GET", "/api/v1/credentials"),
  setCredential: (name: string, value: string) =>
    request<void>("PUT", `/api/v1/credentials/${encodeURIComponent(name)}`, { value }),
  deleteCredential: (name: string) => request<void>("DELETE", `/api/v1/credentials/${encodeURIComponent(name)}`),
  audit: (limit = 100) => request<AuditEntry[]>("GET", `/api/v1/audit?limit=${limit}`),
  testBroker: () => request<BrokerCheck>("POST", "/api/v1/broker/test"),
  portfolio: () => request<Portfolio>("GET", "/api/v1/broker/portfolio"),
  marketStatus: () => request<MarketSession[]>("GET", "/api/v1/market/status"),
  searchInstruments: (q: string) => request<Instrument[]>("GET", `/api/v1/instruments/search?q=${encodeURIComponent(q)}`),
  watchlist: () => request<WatchItem[]>("GET", "/api/v1/watchlist"),
  addToWatchlist: (instrumentId: number) => request<WatchItem>("POST", "/api/v1/watchlist", { instrumentId }),
  removeFromWatchlist: (instrumentId: number) => request<void>("DELETE", `/api/v1/watchlist/${instrumentId}`),
  watchlistQuotes: () => request<Quote[]>("GET", "/api/v1/watchlist/quotes"),
  events: (limit = 50) => request<EventFeed>("GET", `/api/v1/events?limit=${limit}`),
  eventsSeen: () => request<void>("POST", "/api/v1/events/seen"),
  riskLimits: () => request<RiskLimits>("GET", "/api/v1/risk/limits"),
  setRiskLimits: (l: RiskLimits) => request<RiskLimits>("PUT", "/api/v1/risk/limits", l),
  reloadSettings: () => request<void>("POST", "/api/v1/system/reload"),
  restart: () => request<void>("POST", "/api/v1/system/restart"),
  llmSetup: () => request<LlmSetup>("GET", "/api/v1/llm"),
  setLlm: (c: LlmConfig) => request<LlmConfig>("PUT", "/api/v1/llm", c),
  llmModels: (c: LlmConfig) => request<string[]>("POST", "/api/v1/llm/models", c),
  testLlm: () => request<LlmTestResult>("POST", "/api/v1/llm/test"),
  themes: () => request<Theme[]>("GET", "/api/v1/themes"),
  createTheme: (t: ThemeInput) => request<Theme>("POST", "/api/v1/themes", t),
  updateTheme: (id: string, t: ThemeInput) => request<Theme>("PUT", `/api/v1/themes/${encodeURIComponent(id)}`, t),
  deleteTheme: (id: string) => request<void>("DELETE", `/api/v1/themes/${encodeURIComponent(id)}`),
  industries: () => request<Industry[]>("GET", "/api/v1/industries"),
  reviews: (limit = 100) => request<ReviewBoard>("GET", `/api/v1/reviews?limit=${limit}`),
  setScanner: (enabled: boolean) => request<void>("PUT", "/api/v1/scanner", { enabled }),
  runScanner: () => request<ScanResult>("POST", "/api/v1/scanner/run"),
  accounts: () => request<Account[]>("GET", "/api/v1/accounts"),
  createAccount: (name: string, mode: "demo" | "real") => request<Account>("POST", "/api/v1/accounts", { name, mode }),
  setCurrentAccount: (accountId: string) => request<Account>("PUT", "/api/v1/accounts/current", { accountId }),
  renameAccount: (id: string, name: string) => request<Account>("PATCH", `/api/v1/accounts/${encodeURIComponent(id)}`, { name }),
  deleteAccount: (id: string) => request<void>("DELETE", `/api/v1/accounts/${encodeURIComponent(id)}`),
  accountKeys: (id: string) => request<AccountKeys>("GET", `/api/v1/accounts/${encodeURIComponent(id)}/keys`),
  setAccountKeys: (id: string, apiKey: string, userKey: string) =>
    request<void>("PUT", `/api/v1/accounts/${encodeURIComponent(id)}/keys`, { apiKey, userKey }),
  testAccount: (id: string) => request<BrokerCheck>("POST", `/api/v1/accounts/${encodeURIComponent(id)}/test`),
  accountShares: (id: string) => request<AccountShare[]>("GET", `/api/v1/accounts/${encodeURIComponent(id)}/shares`),
  shareAccount: (id: string, username: string, access: "view" | "trade") =>
    request<void>("PUT", `/api/v1/accounts/${encodeURIComponent(id)}/shares`, { username, access }),
  unshareAccount: (id: string, userId: string) =>
    request<void>("DELETE", `/api/v1/accounts/${encodeURIComponent(id)}/shares/${encodeURIComponent(userId)}`),
};

// usd formats US-dollar cents, e.g. 123456 → "$1,234.56".
export function usd(cents: number | undefined): string {
  if (cents === undefined) return "—";
  return (cents / 100).toLocaleString("en-US", { style: "currency", currency: "USD" });
}

export function errorText(e: unknown): string {
  if (e instanceof ApiError) return e.message;
  if (e instanceof Error) return e.message;
  return String(e);
}
